css:
/* briskrew print style */
.print-format {
	font-family: Geist, "Helvetica Neue", Arial, sans-serif;
	font-size: 12.5px;
	color: #0e1433;
	background: white;
}

.print-heading {
	border-bottom: 3px solid #c9f24b;
	padding-bottom: 8px;
	margin-bottom: 16px;
	text-align: left;
}

.print-heading h2 {
	font-size: 24px;
	font-weight: 800;
	letter-spacing: -0.01em;
	color: #0e1433;
}

.print-heading h2 div {
	font-weight: 800;
}

.print-heading small {
	font-size: 12.5px !important;
	font-weight: normal;
	color: #5a6384;
}

.print-format .letter-head {
	margin-bottom: 24px;
}

.print-format label {
	font-weight: 600;
	font-size: 11px;
	text-transform: uppercase;
	letter-spacing: 0.06em;
	color: #5a6384;
	margin-bottom: 0;
}

.print-format .value {
	color: #0e1433;
	line-height: 1.7;
}

.print-format .row:not(.section-break) {
	line-height: 1.6;
	margin-top: 12px !important;
}

.print-format .important .value {
	font-weight: 700;
}

.print-format h3,
.print-format h4,
.print-format .section-title {
	color: #2b3fe0;
	font-weight: 700;
}

.print-format th {
	background-color: #f2f4f9 !important;
	color: #394264;
	font-size: 11px;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: 0.04em;
	border-bottom-width: 1px !important;
}

.print-format .table-bordered,
.print-format .table-bordered td,
.print-format .table-bordered th {
	border: 1px solid #e5e9f2;
}

.print-format td,
.print-format th {
	padding: 7px 10px !important;
}

.print-format .primary.compact-item {
	font-weight: 700;
}
